  const localPageId = data.selectedPageId ?? (pages.some(page => page.id === stored?.localPageId) ? stored?.localPageId : pages[0]?.id);
  const localSourceId = data.selectedSourceId ?? (!pageReplaced && !sourceReplaced && !contentReplaced
