const root = { id: identity, revision: identity, title: visible(240), description: plain(2000).optional() };
const message = plain(2000).optional();
const maximumPayloadBytes = 2 * 1024 * 1024;

function payloadBudget(value: unknown, context: z.RefinementCtx) {
  // A failed nested JSON guard may leave unsafe input here; never serialize it.
  if (context.issues.length) return;
  try {
    if (new TextEncoder().encode(stableReviewKey(value)).byteLength <= maximumPayloadBytes) return;
  } catch { /* Parsed data must have an unambiguous bounded JSON representation. */ }
  context.addIssue({ code: "custom", message: "The complete parsed DTO must fit 2 MiB of UTF-8 JSON." });
}

/** Supplied source metadata, not a claim that the source or its URL was verified. */
export const EvidenceSourceSchema = existingSource.extend({ revision: identity }).strict();
export type EvidenceSource = z.input<typeof EvidenceSourceSchema>;
export type EvidenceSourceInput = EvidenceSource;
export type ParsedEvidenceSource = z.output<typeof EvidenceSourceSchema>;

export const EvidenceContentSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("text"), text: z.string().max(65536) }).strict(),
  z.object({ type: z.literal("json"), value: InspectableJSONSchema }).strict(),
]);
export type EvidenceContent = z.input<typeof EvidenceContentSchema>;
export type ParsedEvidenceContent = z.output<typeof EvidenceContentSchema>;

export const SourceListSchema = z.discriminatedUnion("state", [
  z.object({ ...root, state: z.literal("ready"), sources: z.array(EvidenceSourceSchema).max(100),
    selectedSourceId: identity.nullable().optional(), message }).strict(),
  z.object({ ...root, state: z.literal("loading"), message }).strict(),
  z.object({ ...root, state: z.literal("empty"), message }).strict(),
  z.object({ ...root, state: z.literal("error"), message: visible(2000) }).strict(),
]).superRefine((list, context) => {
  if (list.state === "ready") {
    const ids = new Set(list.sources.map(source => source.id));
    if (ids.size !== list.sources.length) context.addIssue({ code: "custom", path: ["sources"], message: "Source identities must be unique." });
    if (list.selectedSourceId !== undefined && list.selectedSourceId !== null && !ids.has(list.selectedSourceId)) {
      context.addIssue({ code: "custom", path: ["selectedSourceId"], message: "Select a current source." });
    }
  }
  payloadBudget(list, context);
}).describe("Strict supplied source metadata and current selection. The complete parsed DTO fits 2 MiB UTF-8 JSON; sources are not fetched or verified.");
export type SourceListData = z.input<typeof SourceListSchema>;
export type ParsedSourceListData = z.output<typeof SourceListSchema>;

const drawer = { ...root, open: z.boolean().optional() };
export const EvidenceDrawerSchema = z.discriminatedUnion("state", [
  z.object({ ...drawer, state: z.literal("ready"), source: EvidenceSourceSchema, content: EvidenceContentSchema, message }).strict(),
  z.object({ ...drawer, state: z.literal("loading"), source: EvidenceSourceSchema.optional(), message }).strict(),
  z.object({ ...drawer, state: z.literal("empty"), message }).strict(),
  z.object({ ...drawer, state: z.literal("error"), source: EvidenceSourceSchema.optional(), message: visible(2000) }).strict(),
]).superRefine(payloadBudget).describe("Strict caller-supplied evidence with a collective 2 MiB parsed UTF-8 JSON budget. Optional open is an external opening request with owned dismissal; absence is preserved. No fetch, verification or persistence is implied.");
export type EvidenceDrawerData = z.input<typeof EvidenceDrawerSchema>;
export type ParsedEvidenceDrawerData = z.output<typeof EvidenceDrawerSchema>;

type ListScope = { listId: string; listRevision: string; sourceId: string; sourceRevision: string };
export type SourceListIntent =
  | { type: "select-source"; data: ListScope }
  | { type: "inspect-source"; data: ListScope };
type DrawerScope = { drawerId: string; drawerRevision: string } & (
  | { sourceId: string; sourceRevision: string }
  | { sourceId?: never; sourceRevision?: never }
);
export type EvidenceDrawerIntent =
  | { type: "open-evidence"; data: DrawerScope }
  | { type: "close-evidence"; data: DrawerScope };

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent } from "react";
import {
  SourceListSchema, EvidenceDrawerSchema, stableReviewKey,
  type SourceListData, type ParsedSourceListData, type EvidenceDrawerData, type ParsedEvidenceDrawerData,
  type ParsedEvidenceSource, type SourceListIntent, type EvidenceDrawerIntent,
} from "./schemas";
import { Button, Card, InvalidPayload } from "./primitives.js";
import { Feedback } from "./component-helpers.js";
import type { ComponentAction, ComponentProps } from "./component-types.js";

type UIProps = Pick<ComponentProps<unknown>, "className" | "onAction" | "busy" | "error">;
type ReadyList = Extract<ParsedSourceListData, { state: "ready" }>;
const ownData = <T extends object>({ className: _className, onAction: _onAction, busy: _busy, error: _error, ...data }: ComponentProps<T>) => data;
const rootKey = (data: { id: string; revision: string }) => stableReviewKey({ id: data.id, revision: data.revision });
const actionError = "The action could not be completed. Try again.";

export interface SourceSelectionState {
  root: string; localId: string | null; selectedId: string | null; sourceKey?: string;
}

/** Compare the current member only: an unrelated append does not reset a choice. */
export function reconcileSourceSelection(data: ReadyList, previous?: SourceSelectionState): SourceSelectionState {
  const root = rootKey(data), stored = previous?.root === root ? previous : undefined;
  const oldSource = data.sources.find(source => source.id === stored?.selectedId);
  const replaced = Boolean(stored?.selectedId && stableReviewKey(oldSource ?? null) !== stored.sourceKey);
  const localId = stored && !replaced && data.sources.some(source => source.id === stored.localId) ? stored.localId : null;
  const selectedId = data.selectedSourceId === undefined ? localId : data.selectedSourceId;
  const source = data.sources.find(item => item.id === selectedId);
  const next = { root, localId, selectedId, sourceKey: source ? stableReviewKey(source) : undefined };
  return stored && stored.localId === next.localId && stored.selectedId === next.selectedId && stored.sourceKey === next.sourceKey ? stored : next;
}

export interface EvidencePresentationState {
  root: string; content: string; request: boolean | undefined; open: boolean; cycle: number;
}

/** An external true is a consumed request, while user dismissal remains owned here. */
export function reconcileEvidencePresentation(data: ParsedEvidenceDrawerData, previous?: EvidencePresentationState): EvidencePresentationState {
  const { open: request, ...terms } = data, root = rootKey(data), content = stableReviewKey(terms);
  if (!previous || previous.root !== root) return { root, content, request, open: request === true, cycle: (previous?.cycle ?? -1) + 1 };
  const replaced = previous.content !== content, requested = request === true && previous.request !== true;
  const open = request === false ? false : requested ? true : replaced ? false : previous.open;
  const cycle = previous.cycle + (replaced || requested || previous.open !== open ? 1 : 0);
  return !replaced && previous.request === request && previous.open === open && previous.cycle === cycle
    ? previous : { root, content, request, open, cycle };
}

export function changeEvidencePresentation(state: EvidencePresentationState, open: boolean): EvidencePresentationState {
  return { ...state, open, cycle: state.cycle + 1 };
}
const presentationScope = (state: EvidencePresentationState) => stableReviewKey({ root: state.root, content: state.content, cycle: state.cycle });

/** Local notification ownership; settlement can change feedback, never presentation. */
function useEvidenceNotification(scope: string, onAction: UIProps["onAction"], failure = actionError) {
  const available = Boolean(onAction), ownedScope = `${available}:${scope}`;
  const current = useRef({ scope: ownedScope, generation: 0, pendingKey: "", mounted: true });
  const [feedback, setFeedback] = useState<{ scope: string; pending: boolean; error?: string }>({ scope: ownedScope, pending: false });
  if (current.current.scope !== ownedScope) {
    current.current = { ...current.current, scope: ownedScope, generation: current.current.generation + 1, pendingKey: "" };
  }
  useEffect(() => {
    current.current.mounted = true;
    return () => { current.current.mounted = false; current.current.generation += 1; current.current.pendingKey = ""; };
  }, []);
  const send = (intent: ComponentAction, nextScope = scope) => {
    if (!onAction || !current.current.mounted) return;
    const targetScope = `${available}:${nextScope}`, key = stableReviewKey(intent);
    if (current.current.scope === targetScope && current.current.pendingKey === key) return;
    const generation = current.current.generation + 1;
    current.current = { ...current.current, scope: targetScope, generation, pendingKey: key };
    const live = () => current.current.mounted && current.current.scope === targetScope && current.current.generation === generation;
    setFeedback({ scope: targetScope, pending: false });
    try {
      const result: unknown = onAction(intent);
      if (result && typeof (result as PromiseLike<unknown>).then === "function") {
        if (live()) setFeedback({ scope: targetScope, pending: true });
        void Promise.resolve(result).then(() => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false }); }
        }, () => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false, error: failure }); }
        });
      } else if (live()) current.current.pendingKey = "";
    } catch {
      if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false, error: failure }); }
    }
  };
  return { send, pending: feedback.scope === ownedScope && feedback.pending, error: feedback.scope === ownedScope ? feedback.error : undefined };
}

function Header({ title, description }: { title: string; description?: string }) {
  return <header className="mcpcn-header"><h3 className="mcpcn-title">{title}</h3>{description !== undefined && <p className="mcpcn-description">{description}</p>}</header>;
}
function SourceDetails({ source }: { source: ParsedEvidenceSource }) {
  return <div className="mcpcn-source-description">
    <h4>{source.label}</h4>
    {source.url !== undefined && <p><a href={source.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer">{source.url}</a></p>}
    {source.excerpt !== undefined && <p className="mcpcn-source-excerpt">{source.excerpt}</p>}
    {source.supports.length > 0 && <ul aria-label={`Supplied support: ${source.label}`}>{source.supports.map((support, index) => <li key={index}>{support}</li>)}</ul>}
  </div>;
}
function SourceRow({ data, source, selected, choose, ...props }: UIProps & {
  data: ReadyList; source: ParsedEvidenceSource; selected: boolean; choose: (source: ParsedEvidenceSource) => void;
}) {
  const action = useEvidenceNotification(stableReviewKey({ root: rootKey(data), source }), props.onAction);
  const blocked = Boolean(props.busy || action.pending), controlledWithoutCallback = data.selectedSourceId !== undefined && !props.onAction;
  const intent = (type: SourceListIntent["type"]): SourceListIntent => ({ type, data: { listId: data.id, listRevision: data.revision, sourceId: source.id, sourceRevision: source.revision } });
  return <li className="mcpcn-source-item"><SourceDetails source={source} /><div className="mcpcn-row">
    <Button type="button" data-variant="secondary" aria-label={`Select source: ${source.label}`} aria-pressed={selected} disabled={blocked || controlledWithoutCallback}
      onClick={() => { if (blocked || controlledWithoutCallback) return; choose(source); action.send(intent("select-source")); }}>Select source</Button>
    <Button type="button" data-variant="secondary" aria-label={`Inspect source: ${source.label}`} disabled={blocked || !props.onAction}
      onClick={() => action.send(intent("inspect-source"))}>Inspect source</Button>
  </div><Feedback busy={action.pending} error={action.error} /></li>;
}

export function SourceList(props: ComponentProps<SourceListData>) {
  const parsed = SourceListSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Source list is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <SourceListView key={rootKey(parsed.data)} data={parsed.data} className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}
function SourceListView({ data, ...props }: UIProps & { data: ParsedSourceListData }) {
  return <Card className={["mcpcn-source-root", props.className].filter(Boolean).join(" ")} role="region" aria-label={data.title} aria-busy={Boolean(props.busy)}>
    <Header {...data} /><div className="mcpcn-body mcpcn-stack">
      <p className="mcpcn-hint">Sources and support are supplied claims, not verified evidence.</p>
      {data.state === "ready" ? <ReadySources data={data} {...props} /> : data.state === "loading" ? <p role="status">Source list is loading.</p>
        : data.state === "empty" ? <p role="status">No sources were supplied.</p> : null}
      {data.message !== undefined && <p role={data.state === "error" ? "alert" : undefined}>{data.message}</p>}
      <Feedback busy={props.busy} error={props.error} />
    </div></Card>;
}
function ReadySources({ data, ...props }: UIProps & { data: ReadyList }) {
  const [stored, setStored] = useState(() => reconcileSourceSelection(data));
  const state = reconcileSourceSelection(data, stored);
  if (state !== stored) setStored(state);
  return data.sources.length === 0 ? <p role="status">No sources were supplied.</p> : <ul className="mcpcn-source-list" aria-label="Supplied sources">
    {data.sources.map(source => <SourceRow key={source.id} data={data} source={source} selected={state.selectedId === source.id} {...props}
      choose={selected => { if (data.selectedSourceId === undefined) setStored({ ...state, localId: selected.id, selectedId: selected.id, sourceKey: stableReviewKey(selected) }); }} />)}
  </ul>;
}

function restoreInvoker(invoker: HTMLElement | null, dialog: HTMLDialogElement) {
  if (!invoker?.isConnected || invoker.ownerDocument !== dialog.ownerDocument || invoker.closest("[inert],[hidden],[aria-hidden='true']")
    || "disabled" in invoker && Boolean(invoker.disabled) || invoker.getClientRects().length === 0) return;
  const style = invoker.ownerDocument.defaultView?.getComputedStyle(invoker);
  if (style?.visibility === "hidden" || style?.display === "none") return;
  try {
    const modals = [...dialog.ownerDocument.querySelectorAll("dialog:modal")];
    if (modals.some(modal => modal !== dialog && !modal.contains(invoker))) return;
    if (dialog.ownerDocument.activeElement !== invoker) invoker.focus({ preventScroll: true });
  } catch { /* Unsupported native modality cannot justify moving another scope's focus. */ }
}

export function EvidenceDrawer(props: ComponentProps<EvidenceDrawerData>) {
  const parsed = EvidenceDrawerSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Evidence drawer is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <EvidenceDrawerView data={parsed.data} className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}
function EvidenceDrawerView({ data, ...props }: UIProps & { data: ParsedEvidenceDrawerData }) {
  const [stored, setStored] = useState(() => reconcileEvidencePresentation(data));
  const state = reconcileEvidencePresentation(data, stored);
  if (state !== stored) setStored(state);
  const live = useRef(state); live.current = state;
  const dialog = useRef<HTMLDialogElement>(null), heading = useRef<HTMLHeadingElement>(null), invoker = useRef<HTMLElement | null>(null);
  const backdrop = useRef<number | null>(null), labelId = useId(), dialogId = useId();
  const [promoted, setPromoted] = useState(false), [modalError, setModalError] = useState<{ scope: string; message: string }>();
  const scope = presentationScope(state), notification = useEvidenceNotification(scope, props.onAction, "The view request could not be reported. Try again.");
  const source = "source" in data ? data.source : undefined;
  const intent = (type: EvidenceDrawerIntent["type"]): EvidenceDrawerIntent => ({ type, data: source === undefined
    ? { drawerId: data.id, drawerRevision: data.revision }
    : { drawerId: data.id, drawerRevision: data.revision, sourceId: source.id, sourceRevision: source.revision } });
  const change = (open: boolean) => {
    const next = changeEvidencePresentation(live.current, open); live.current = next; setStored(next); return next;
  };
  const dismiss = () => {
    if (!live.current.open && !dialog.current?.open) return;
    const next = change(false); backdrop.current = null;
    if (dialog.current?.open) dialog.current.close();
    setPromoted(false);
    if (dialog.current) restoreInvoker(invoker.current, dialog.current);
    notification.send(intent("close-evidence"), presentationScope(next));
  };
  useEffect(() => {
    const node = dialog.current;
    if (!node || !state.open) { setPromoted(false); return; }
    const owner = invoker.current?.isConnected ? invoker.current : node.ownerDocument.activeElement;
    const previousFocus = owner instanceof HTMLElement ? owner : null;
    invoker.current = previousFocus;
    try {
      if (!node.isConnected || typeof node.showModal !== "function" || typeof node.close !== "function") throw new Error("modal_unavailable");
      if (!node.open) node.showModal();
      if (!node.open || !node.matches(":modal")) throw new Error("modal_not_promoted");
      setPromoted(true); setModalError(undefined); heading.current?.focus({ preventScroll: true });
    } catch {
      if (node.open && typeof node.close === "function") node.close();
      const next = changeEvidencePresentation(live.current, false); live.current = next; setStored(next); setPromoted(false);
      setModalError({ scope: next.content, message: "The evidence drawer could not open as a modal." });
    }
    return () => {
      if (node.open) node.close();
      restoreInvoker(previousFocus, node);
      invoker.current = null;
    };
  }, [state.open, state.cycle]);
  const outside = (event: PointerEvent<HTMLDialogElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    return event.target === event.currentTarget && (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom);
  };
  const containTab = (event: KeyboardEvent<HTMLDialogElement>) => {
    const node = event.currentTarget, active = node.ownerDocument.activeElement;
    if (event.key !== "Tab" || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.nativeEvent.isComposing
      || !node.open || !node.matches(":modal") || !node.contains(active)) return;
    const stops = [...node.querySelectorAll<HTMLElement>("button,input,select,textarea,a[href],summary,[tabindex]")].filter(element => {
      if (!element.isConnected || element.tabIndex < 0 || element.matches(":disabled")
        || element.closest("[hidden],[inert],[aria-hidden='true']") || element.getClientRects().length === 0) return false;
      const style = node.ownerDocument.defaultView?.getComputedStyle(element);
      if (!style || style.display === "none" || style.visibility === "hidden" || style.visibility === "collapse") return false;
      for (let parent = element.parentElement; parent && parent !== node; parent = parent.parentElement) {
        if (parent.tagName === "DETAILS" && !parent.hasAttribute("open") && !parent.querySelector(":scope > summary")?.contains(element)) return false;
      }
      return true;
    });
    // A child document's native sequence can otherwise continue into its host.
    if (stops.length === 0) { event.preventDefault(); heading.current?.focus({ preventScroll: true }); return; }
    const index = stops.indexOf(active as HTMLElement);
    const next = event.shiftKey ? index <= 0 ? stops.at(-1) : undefined : index < 0 || index === stops.length - 1 ? stops[0] : undefined;
    if (next) { event.preventDefault(); next.focus(); }
  };
  const feedback = <Feedback busy={Boolean(props.busy || notification.pending)} error={props.error ?? notification.error ?? (modalError?.scope === state.content ? modalError.message : undefined)} />;
  return <Card className={["mcpcn-evidence-root", props.className].filter(Boolean).join(" ")} role="region" aria-label={data.title} aria-busy={Boolean(props.busy || notification.pending)}>
    <Header {...data} /><div className="mcpcn-body mcpcn-stack">
      <p className="mcpcn-hint">Evidence is supplied for inspection; its contents are not independently verified.</p>
      <Button type="button" aria-label="Open evidence" aria-haspopup="dialog" aria-controls={dialogId} aria-expanded={promoted}
        disabled={data.open === false && !props.onAction} onClick={event => {
          invoker.current = event.currentTarget;
          if (data.open === false) { notification.send(intent("open-evidence")); return; }
          if (live.current.open) return;
          const next = change(true); notification.send(intent("open-evidence"), presentationScope(next));
        }}>Open evidence</Button>
      {!promoted && feedback}
    </div>
    <dialog ref={dialog} id={dialogId} className="mcpcn mcpcn-evidence-dialog" aria-labelledby={labelId} data-presentation-open={state.open}
      onKeyDown={containTab}
      onCancel={event => { event.preventDefault(); dismiss(); }}
      onClose={event => { if (event.currentTarget.open || !live.current.open) return; change(false); setPromoted(false); restoreInvoker(invoker.current, event.currentTarget); }}
      onPointerDown={event => { backdrop.current = event.button === 0 && outside(event) ? event.pointerId : null; }}
      onPointerUp={event => { const close = backdrop.current === event.pointerId && outside(event); backdrop.current = null; if (close) dismiss(); }}
      onPointerCancel={() => { backdrop.current = null; }}>
      <header className="mcpcn-header mcpcn-row mcpcn-between"><h2 ref={heading} id={labelId} className="mcpcn-title" tabIndex={-1}>{data.title}</h2>
        <Button type="button" data-variant="secondary" aria-label="Close evidence" onClick={dismiss}>Close evidence</Button></header>
      <div key={state.content} className="mcpcn-evidence-content mcpcn-stack" role="region" aria-label="Supplied evidence content" tabIndex={0}>
        {data.description !== undefined && <p className="mcpcn-description">{data.description}</p>}
        {source !== undefined && <SourceDetails source={source} />}
        {data.state === "ready" ? data.content.type === "text" ? <pre className="mcpcn-evidence-text">{data.content.text}</pre>
          : <details open><summary>Evidence JSON</summary><pre className="mcpcn-code">{JSON.stringify(data.content.value, null, 2)}</pre></details>
          : data.state === "loading" ? <p role="status">Evidence is loading.</p> : data.state === "empty" ? <p role="status">No evidence was supplied.</p> : null}
        {data.message !== undefined && <p role={data.state === "error" ? "alert" : undefined}>{data.message}</p>}
        <p className="mcpcn-hint">Sources and support are supplied claims, not verified evidence.</p>{promoted && feedback}
      </div>
    </dialog>
  </Card>;
}

import { z } from "zod";
import { InspectableJSONSchema } from "./execution-schemas.js";
import { FileExtractionFieldSchema, stableReviewKey } from "./file-review-schemas.js";

const extracted = FileExtractionFieldSchema.shape;
const identity = extracted.id;
const controls = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/;
const plain = (maximum: number) => z.string().max(maximum).refine(value => !controls.test(value), "Use plain text without unsupported control characters.");
const label = extracted.label.refine(value => !controls.test(value), "Supply visible plain text.");
const root = { id: identity, revision: identity, title: label, description: plain(4000).optional() };
const message = plain(4000).optional();
const failure = plain(4000).refine(value => Boolean(value.trim()), "Supply a nonblank failure message.");

function safeDTO(value: unknown): boolean {
  let nodes = 0;
  const ancestors = new Set<object>();
  function visit(item: unknown, depth: number): boolean {
    // A record DTO adds four levels above each unchanged depth-eight JSON value.
    // 100 fields with 1000 JSON nodes and 20 evidence objects fit below this bound.
    if (++nodes > 120000 || depth > 12) return false;
    if (item === undefined || item === null || typeof item === "boolean") return true;
    if (typeof item === "number") return Number.isFinite(item);
    if (typeof item === "string") return item.length <= 10000;
    if (typeof item !== "object" || ancestors.has(item) || Object.getOwnPropertySymbols(item).length > 0) return false;
    const array = Array.isArray(item), prototype = Object.getPrototypeOf(item);
    if (array ? prototype !== Array.prototype : prototype !== Object.prototype && prototype !== null) return false;
    const descriptors = Object.getOwnPropertyDescriptors(item);
    const keys = Object.keys(descriptors).filter(key => !(array && key === "length"));
    if (keys.length > 200 || (array && (descriptors.length?.value !== keys.length || keys.some((key, index) => key !== String(index))))) return false;
    ancestors.add(item);
    try {
      return keys.every(key => {
        const descriptor = descriptors[key];
        return key.length <= 256 && descriptor !== undefined && descriptor.enumerable === true
          && "value" in descriptor && visit(descriptor.value, depth + 1);
      });
    } finally { ancestors.delete(item); }
  }
  try { return visit(value, 0); } catch { return false; }
}

function dtoGuard<T>() {
  return z.unknown().superRefine((value, context) => {
    if (!safeDTO(value)) context.addIssue({ code: "custom", message: "Supply bounded plain DTOs without accessors, symbols, cycles or foreign prototypes." });
  }) as z.ZodType<T, T>;
}

function payloadBudget(value: unknown, context: z.RefinementCtx) {
  // Nested JSON may be rejected: never serialize it while any issue remains.
  if (context.issues.length) return;
  try {
    if (new TextEncoder().encode(stableReviewKey(value)).byteLength <= 2 * 1024 * 1024) return;
  } catch { /* A parsed DTO must have an unambiguous bounded JSON representation. */ }
  context.addIssue({ code: "custom", message: "The complete parsed DTO must fit 2 MiB of UTF-8 JSON." });
}

const field = z.object({
  id: identity, revision: identity, label, value: InspectableJSONSchema,
  confidence: extracted.confidence, evidence: extracted.evidence,
}).strict();
export const InspectionFieldSchema = dtoGuard<z.input<typeof field>>().pipe(field);
export type InspectionField = z.input<typeof InspectionFieldSchema>;
export type ParsedInspectionField = z.output<typeof InspectionFieldSchema>;

const fields = z.array(InspectionFieldSchema).max(100).refine(value => new Set(value.map(item => item.id)).size === value.length, "Field identities must be unique.");
const selected = identity.nullable().optional();
const record = z.object({ id: identity, revision: identity, label, fields }).strict();

const inspector = z.discriminatedUnion("state", [
  z.object({ ...root, state: z.literal("ready"), record, selectedFieldId: selected, message }).strict(),
  z.object({ ...root, state: z.literal("loading"), message }).strict(),
  z.object({ ...root, state: z.literal("empty"), message }).strict(),
  z.object({ ...root, state: z.literal("error"), message: failure }).strict(),
]).superRefine((value, context) => {
  if (value.state === "ready" && value.selectedFieldId !== undefined && value.selectedFieldId !== null
    && !value.record.fields.some(item => item.id === value.selectedFieldId)) {
    context.addIssue({ code: "custom", path: ["selectedFieldId"], message: "Select a current field in this record." });
  }
  payloadBudget(value, context);
});
export const RecordInspectorSchema = dtoGuard<z.input<typeof inspector>>().pipe(inspector)
  .describe("Strict supplied record fields, complete guarded JSON values and identity-only selection. Parsed data fits 2 MiB UTF-8 JSON. Confidence and evidence are supplied claims, not verification.");
export type RecordInspectorData = z.input<typeof RecordInspectorSchema>;
export type ParsedRecordInspectorData = z.output<typeof RecordInspectorSchema>;

const confidenceList = z.discriminatedUnion("state", [
  z.object({ ...root, state: z.literal("ready"), fields, selectedFieldId: selected, message }).strict(),
  z.object({ ...root, state: z.literal("loading"), message }).strict(),
  z.object({ ...root, state: z.literal("empty"), message }).strict(),
  z.object({ ...root, state: z.literal("error"), message: failure }).strict(),
]).superRefine((value, context) => {
  if (value.state === "ready" && value.selectedFieldId !== undefined && value.selectedFieldId !== null
    && !value.fields.some(item => item.id === value.selectedFieldId)) {
    context.addIssue({ code: "custom", path: ["selectedFieldId"], message: "Select a current confidence field." });
  }
  payloadBudget(value, context);
});
export const FieldConfidenceListSchema = dtoGuard<z.input<typeof confidenceList>>().pipe(confidenceList)
  .describe("Strict supplied field confidence and complete guarded values, with a collective 2 MiB parsed UTF-8 JSON limit. Absent confidence differs from zero; no confidence threshold or authenticity is inferred.");
export type FieldConfidenceListData = z.input<typeof FieldConfidenceListSchema>;
export type ParsedFieldConfidenceListData = z.output<typeof FieldConfidenceListSchema>;

type ComponentScope = { componentId: string; componentRevision: string };
type RecordScope = ComponentScope & { recordId: string; recordRevision: string };
type FieldScope = { fieldId: string; fieldRevision: string };
export type RecordInspectorIntent =
  | { type: "inspect-record-field"; data: RecordScope & FieldScope }
  | { type: "clear-record-field"; data: RecordScope };
export type FieldConfidenceListIntent =
  | { type: "inspect-confidence-field"; data: ComponentScope & FieldScope }
  | { type: "clear-confidence-field"; data: ComponentScope };

"use client";

import { useEffect, useRef, useState } from "react";
import {
  RecordInspectorSchema, FieldConfidenceListSchema, stableReviewKey,
  type RecordInspectorData, type ParsedRecordInspectorData,
  type FieldConfidenceListData, type ParsedFieldConfidenceListData, type ParsedInspectionField,
  type RecordInspectorIntent, type FieldConfidenceListIntent,
} from "./schemas";
import { Button, Card, InvalidPayload } from "./primitives.js";
import { Feedback } from "./component-helpers.js";
import type { ComponentAction, ComponentProps } from "./component-types.js";

type UIProps = Pick<ComponentProps<unknown>, "className" | "onAction" | "busy" | "error">;
type InspectionData = ParsedRecordInspectorData | ParsedFieldConfidenceListData;
type ReadyInspection = Extract<InspectionData, { state: "ready" }>;
type InspectionIntent = RecordInspectorIntent | FieldConfidenceListIntent;
function ownData(props: object): unknown {
  try {
    const descriptors = Object.getOwnPropertyDescriptors(props), data: object = Object.create(Object.getPrototypeOf(props));
    for (const key of Reflect.ownKeys(descriptors)) {
      const descriptor = Object.getOwnPropertyDescriptor(descriptors, key)?.value as PropertyDescriptor | undefined;
      if (!descriptor) return null;
      if (typeof key === "string" && (["className", "onAction", "busy", "error"].includes(key) || key === "key" && descriptor.enumerable === false)) continue;
      Object.defineProperty(data, key, descriptor);
    }
    return data;
  } catch { return null; }
}
const fieldsOf = (data: ReadyInspection) => "record" in data ? data.record.fields : data.fields;
const inspectionRoot = (data: ReadyInspection) => stableReviewKey("record" in data
  ? { kind: "record", id: data.id, revision: data.revision, recordId: data.record.id, recordRevision: data.record.revision }
  : { kind: "confidence", id: data.id, revision: data.revision });

export interface InspectionSelectionState {
  root: string; localId: string | null; selectedId: string | null; fieldKey?: string;
}

/** Only the current member participates in local replacement reconciliation. */
export function reconcileInspectionSelection(data: ReadyInspection, previous?: InspectionSelectionState): InspectionSelectionState {
  const root = inspectionRoot(data), stored = previous?.root === root ? previous : undefined, fields = fieldsOf(data);
  const oldField = fields.find(field => field.id === stored?.selectedId);
  const replaced = Boolean(stored?.selectedId && stableReviewKey(oldField ?? null) !== stored.fieldKey);
  const localId = stored && !replaced && fields.some(field => field.id === stored.localId) ? stored.localId : null;
  const selectedId = data.selectedFieldId === undefined ? localId : data.selectedFieldId;
  const selected = fields.find(field => field.id === selectedId);
  const next = { root, localId, selectedId, fieldKey: selected ? stableReviewKey(selected) : undefined };
  return stored && stored.localId === next.localId && stored.selectedId === next.selectedId && stored.fieldKey === next.fieldKey ? stored : next;
}

/** A requested member is fenced even before a controlled producer selects it. */
export function inspectionNotificationScope(data: ReadyInspection, selectedId: string | null, requestedId: string | null, available: boolean): string {
  const fields = fieldsOf(data);
  return stableReviewKey({ root: inspectionRoot(data), controlled: data.selectedFieldId !== undefined, available,
    selectedId, selected: fields.find(field => field.id === selectedId) ?? null,
    requestedId, requested: fields.find(field => field.id === requestedId) ?? null });
}

function useInspectionNotification(data: ReadyInspection, selectedId: string | null, onAction: UIProps["onAction"]) {
  const available = Boolean(onAction);
  const current = useRef({ scope: "", requestedId: null as string | null, generation: 0, pendingKey: "", mounted: true });
  const scope = inspectionNotificationScope(data, selectedId, current.current.requestedId, available);
  const [feedback, setFeedback] = useState<{ scope: string; pending: boolean; error?: string }>({ scope, pending: false });
  if (current.current.scope !== scope) current.current = { ...current.current, scope, generation: current.current.generation + 1, pendingKey: "" };
  useEffect(() => {
    current.current.mounted = true;
    return () => { current.current.mounted = false; current.current.generation += 1; current.current.pendingKey = ""; };
  }, []);
  const send = (intent: ComponentAction, nextSelectedId: string | null, requestedId: string | null) => {
    if (!onAction || !current.current.mounted) return;
    const targetScope = inspectionNotificationScope(data, nextSelectedId, requestedId, available), key = stableReviewKey(intent);
    if (current.current.scope === targetScope && current.current.pendingKey === key) return;
    const generation = current.current.generation + 1;
    current.current = { ...current.current, scope: targetScope, requestedId, generation, pendingKey: key };
    const live = () => current.current.mounted && current.current.scope === targetScope && current.current.generation === generation;
    setFeedback({ scope: targetScope, pending: false });
    try {
      const result: unknown = onAction(intent);
      if (result && typeof (result as PromiseLike<unknown>).then === "function") {
        if (live()) setFeedback({ scope: targetScope, pending: true });
        void Promise.resolve(result).then(() => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false }); }
        }, () => {
          if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false, error: "The action could not be completed. Try again." }); }
        });
      } else if (live()) current.current.pendingKey = "";
    } catch {
      if (live()) { current.current.pendingKey = ""; setFeedback({ scope: targetScope, pending: false, error: "The action could not be completed. Try again." }); }
    }
  };
  return { send, pending: feedback.scope === scope && feedback.pending, error: feedback.scope === scope ? feedback.error : undefined };
}

function fieldIntent(data: ReadyInspection, field?: ParsedInspectionField): InspectionIntent {
  if ("record" in data) {
    const identity = { componentId: data.id, componentRevision: data.revision, recordId: data.record.id, recordRevision: data.record.revision };
    return field ? { type: "inspect-record-field", data: { ...identity, fieldId: field.id, fieldRevision: field.revision } }
      : { type: "clear-record-field", data: identity };
  }
  const identity = { componentId: data.id, componentRevision: data.revision };
  return field ? { type: "inspect-confidence-field", data: { ...identity, fieldId: field.id, fieldRevision: field.revision } }
    : { type: "clear-confidence-field", data: identity };
}

function FieldConfidence({ field }: { field: ParsedInspectionField }) {
  return <div className="mcpcn-inspection-confidence"><span>Reported confidence: {field.confidence === undefined ? "Not supplied" : `${field.confidence * 100}%`}</span>
    {field.confidence !== undefined && <meter min={0} max={1} value={field.confidence} aria-label={`Reported confidence: ${field.label}`} aria-valuetext={`${field.confidence * 100}%`} />}</div>;
}
const valueType = (value: ParsedInspectionField["value"]) => value === null ? "null" : Array.isArray(value) ? "array" : typeof value;

function SelectedField({ field }: { field: ParsedInspectionField }) {
  return <div className="mcpcn-inspection-content" role="region" aria-label={`Complete value and evidence: ${field.label}`} tabIndex={0}>
    <h4>{field.label}</h4><p className="mcpcn-hint">Field type: {valueType(field.value)}</p><FieldConfidence field={field} />
    <h5>Complete value</h5><pre className="mcpcn-code" aria-label="Complete field JSON">{JSON.stringify(field.value, null, 2)}</pre>
    <h5>Supplied field evidence</h5>{field.evidence.length > 0 ? <ul aria-label="Supplied field evidence" className="mcpcn-inspection-evidence">
      {field.evidence.map(evidence => <li key={evidence.id}><strong>{evidence.label}</strong>
        {evidence.text !== undefined && <p className="mcpcn-inspection-text">{evidence.text}</p>}
        {evidence.url !== undefined && <p><a href={evidence.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer">{evidence.url}</a></p>}
      </li>)}
    </ul> : <p>No evidence was supplied for this field.</p>}
  </div>;
}

function ReadyFields({ data, ...props }: UIProps & { data: ReadyInspection }) {
  const [stored, setStored] = useState(() => reconcileInspectionSelection(data));
  const state = reconcileInspectionSelection(data, stored);
  if (state !== stored) setStored(state);
  const fields = fieldsOf(data), selected = fields.find(field => field.id === state.selectedId);
  const notification = useInspectionNotification(data, state.selectedId, props.onAction);
  const controlled = data.selectedFieldId !== undefined, blocked = controlled && !props.onAction;
  const select = (field: ParsedInspectionField) => {
    if (blocked) return;
    if (!controlled) setStored({ ...state, localId: field.id, selectedId: field.id, fieldKey: stableReviewKey(field) });
    notification.send(fieldIntent(data, field), controlled ? state.selectedId : field.id, field.id);
  };
  return <>
    {"record" in data && <p className="mcpcn-inspection-text"><strong>Record: </strong>{data.record.label}</p>}
    <p className="mcpcn-hint">Select a field to inspect its complete value and supplied evidence.</p>
    <p className="mcpcn-hint">Confidence and evidence are supplied claims, not verified accuracy or authorization.</p>
    {fields.length === 0 ? <p role="status">No fields were supplied.</p> : <ul className="mcpcn-inspection-fields" aria-label={"record" in data ? "Record fields" : "Fields with reported confidence"}>
      {fields.map(field => <li key={field.id} className="mcpcn-inspection-field"><div className="mcpcn-inspection-summary"><strong>{field.label}</strong>
        <span className="mcpcn-hint">Field type: {valueType(field.value)}</span><FieldConfidence field={field} /></div>
        <Button type="button" data-variant="secondary" aria-label={`Inspect field: ${field.label}`} aria-pressed={state.selectedId === field.id} disabled={blocked} onClick={() => select(field)}>Inspect field</Button>
      </li>)}
    </ul>}
    <div><Button type="button" data-variant="secondary" disabled={blocked || state.selectedId === null} onClick={() => {
      if (blocked || state.selectedId === null) return;
      if (!controlled) setStored({ ...state, localId: null, selectedId: null, fieldKey: undefined });
      notification.send(fieldIntent(data), controlled ? state.selectedId : null, null);
    }}>Clear selection</Button></div>
    {selected ? <SelectedField key={selected.id} field={selected} /> : <p role="status">No field is selected.</p>}
    <Feedback busy={notification.pending} error={notification.error} />
  </>;
}

function InspectionView({ data, kind, ...props }: UIProps & { data: InspectionData; kind: "record" | "confidence" }) {
  return <Card className={["mcpcn-inspection-root", props.className].filter(Boolean).join(" ")} role="region" aria-label={data.title} aria-busy={Boolean(props.busy)}>
    <header className="mcpcn-header"><h3 className="mcpcn-title">{data.title}</h3>{data.description !== undefined && <p className="mcpcn-description">{data.description}</p>}</header>
    <div className="mcpcn-body mcpcn-stack">{data.state === "ready" ? <ReadyFields data={data} {...props} />
      : data.state === "loading" ? <p role="status">{kind === "record" ? "Record is loading." : "Field confidence is loading."}</p>
        : data.state === "empty" ? <p role="status">{kind === "record" ? "No record was supplied." : "No fields were supplied."}</p> : null}
      {data.message !== undefined && <p className="mcpcn-inspection-text" role={data.state === "error" ? "alert" : undefined}>{data.message}</p>}
      <Feedback busy={props.busy} error={props.error} />
    </div>
  </Card>;
}

export function RecordInspector(props: ComponentProps<RecordInspectorData>) {
  const parsed = RecordInspectorSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Record inspection data is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <InspectionView data={parsed.data} kind="record" className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}

export function FieldConfidenceList(props: ComponentProps<FieldConfidenceListData>) {
  const parsed = FieldConfidenceListSchema.safeParse(ownData(props));
  if (!parsed.success) return <InvalidPayload title="Field confidence data is invalid" issues={parsed.error.issues.map(issue => issue.message)} />;
  return <InspectionView data={parsed.data} kind="confidence" className={props.className} busy={props.busy} error={props.error} onAction={props.onAction} />;
}

