.mcpcn-inspection-fields{list-style:none;padding:0;margin:0;display:grid;gap:12px}
.mcpcn-inspection-field{min-width:0;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;border:1px solid var(--mcpcn-line);border-radius:9px;padding:14px}
.mcpcn-inspection-summary{min-width:0;display:grid;gap:4px}.mcpcn-inspection-confidence{display:grid;gap:4px}.mcpcn-inspection-confidence meter{width:min(18rem,100%)}
.mcpcn-inspection-root .mcpcn-button{min-height:44px}.mcpcn-inspection-text{white-space:pre-wrap;overflow-wrap:anywhere}
.mcpcn-inspection-content{min-width:0;max-width:100%;max-height:min(70vh,42rem);overflow:auto;overscroll-behavior:contain;border:1px solid var(--mcpcn-line);border-radius:9px;padding:16px}
.mcpcn-inspection-content h4{margin-top:0}.mcpcn-inspection-content:focus-visible{outline:3px solid color-mix(in srgb,var(--mcpcn-accent) 45%,transparent);outline-offset:3px}
.mcpcn-inspection-root .mcpcn-inspection-content pre{max-height:none;overflow:visible;white-space:pre-wrap;overflow-wrap:anywhere}
.mcpcn-inspection-evidence{padding-left:20px}.mcpcn-inspection-evidence li{min-width:0}.mcpcn-inspection-evidence p{margin:8px 0}
@media(max-width:520px){.mcpcn-inspection-field{align-items:flex-start}.mcpcn-inspection-content{padding:12px}}

:root { --mcpcn-accent: #6558e8; --mcpcn-radius: 14px; }
[data-mcpcn-theme="graphite"] { --mcpcn-accent: #27272a; --mcpcn-radius: 10px; }
[data-mcpcn-theme="violet"] { --mcpcn-accent: #7c3aed; --mcpcn-radius: 18px; }

"use client";

import { useEffect, useState, type ReactNode } from "react";
import { AgentAppProvider, detectAdapter, type AgentAppAdapter } from "./_mcpcn/runtime";
import "./styles.css";

export function MCPCNProvider({ children }: { children: ReactNode }) {
  const [adapter, setAdapter] = useState<AgentAppAdapter | null>(null);
  useEffect(() => { setAdapter(detectAdapter()); }, []);
  return <div className="mcpcn" data-mcpcn-theme="default">
    {adapter ? <AgentAppProvider adapter={adapter}>{children}</AgentAppProvider>
      : <p role="status" aria-busy="true">Preparing app connection…</p>}
  </div>;
}
